        !nll_pass?"candidate_nll_regression":!language_pass?"candidate_language_nll_regression":!script_pass?"candidate_expected_script_fraction_too_low":!utf8_pass?"candidate_invalid_utf8":
        !absolute_repetition_pass?"candidate_exceeds_absolute_repetition_limit":!regression_pass?"candidate_repetition_regressed":
        teacher_enabled&&!teacher_pass&&strcmp(teacher_status,"judged")?"teacher_judgment_unavailable":teacher_enabled&&!teacher_pass?"teacher_did_not_prefer_candidate":"candidate_repetition_regressed";
    const char *selected=accepted?argv[2]:argv[1];if(!copy_atomic(selected,argv[5]))goto done;size_t sl=strlen(argv[5]);char *tokpath=(char*)malloc(sl+5);if(!tokpath)goto done;memcpy(tokpath,argv[5],sl);memcpy(tokpath+sl,".tok",5);ok=ama10_tokenizer_save(accepted?&ct:&rt,tokpath);free(tokpath);if(!ok)goto done;
    FILE *f=fopen(argv[4],"wb");if(!f)goto done;int wr=fprintf(f,"{\n  \"decision\": \"%s\",\n  \"reason\": \"%s\",\n  \"reference_checkpoint\": ",accepted?"accept":"rollback",reason);
    if(wr>=0)wr=json_string(f,argv[1]);
    if(wr>=0)wr=fprintf(f,",\n  \"candidate_checkpoint\": ");
    if(wr>=0)wr=json_string(f,argv[2]);
    if(wr>=0)wr=fprintf(f,",\n  \"selected_checkpoint\": ");
    if(wr>=0)wr=json_string(f,selected);
    if(wr>=0)wr=fprintf(f,",\n  \"validation_hash\": \"%016llx\",\n  \"validation_tokens\": %llu,\n  \"reference_nll\": %.9f,\n  \"candidate_nll\": %.9f,\n  \"nll_regression_tolerance\": %.9f,\n  \"language_nll_regression_tolerance\": %.9f,\n  \"language_gate_enabled\": %s,\n  \"script_gate_enabled\": %s,\n  \"minimum_expected_script_fraction\": %.9f,\n  \"max_repeated_fourgram_ratio\": %.9f,\n  \"reference_repeat4\": %.6f,\n  \"candidate_repeat4\": %.6f,\n  \"reference_invalid_utf8\": %llu,\n  \"candidate_invalid_utf8\": %llu,\n  \"teacher\": {\"enabled\": %s, \"status\": ", (unsigned long long)hash,(unsigned long long)rd.token_count,rn,cn,tolerance,language_tolerance,language_count?"true":"false",script_gate_enabled?"true":"false",min_script_fraction,max_repetition,rg.repeated_fourgram_ratio,cg.repeated_fourgram_ratio,(unsigned long long)rg.invalid_utf8_bytes,(unsigned long long)cg.invalid_utf8_bytes,teacher_enabled?"true":"false");
    if(wr>=0)wr=json_string(f,teacher_enabled?"true":"false");
    if(wr>=0)wr=fprintf(f,", \"status\": ");
    if(wr>=0)wr=json_string(f,teacher_status);
    if(wr>=0)wr=fprintf(f,", \"model\": ");
    if(wr>=0)wr=json_string(f,teacher_model);
    if(wr>=0)wr=fprintf(f,", \"choice\": ");
    if(wr>=0)wr=json_string(f,teacher_choice);
    if(wr>=0)wr=fprintf(f,", \"score_reference\": %d, \"score_candidate\": %d},\n  \"language_validation\": [",teacher_score_reference,teacher_score_candidate);
    for(size_t i=0;wr>=0&&i<language_count;i++){if(i)wr=fprintf(f,",");if(wr>=0)wr=fprintf(f,"\n    {\"language\": ");if(wr>=0)wr=json_string(f,language_evals[i].name);if(wr>=0)wr=fprintf(f,", \"expected_script\": ");if(wr>=0)wr=json_string(f,script_name(language_evals[i].script));if(wr>=0)wr=fprintf(f,", \"expected_script_fraction\": %.9f, \"script_passed\": %s, \"validation_path\": ",language_evals[i].script_fraction,language_evals[i].script_pass?"true":"false");if(wr>=0)wr=json_string(f,language_evals[i].path);if(wr>=0)wr=fprintf(f,", \"validation_hash\": \"%016llx\", \"validation_tokens\": %llu, \"reference_nll\": %.9f, \"candidate_nll\": %.9f, \"regression\": %.9f, \"passed\": %s}",(unsigned long long)language_evals[i].hash,(unsigned long long)language_evals[i].reference_data.token_count,language_evals[i].reference_nll,language_evals[i].candidate_nll,language_evals[i].candidate_nll-language_evals[i].reference_nll,language_evals[i].candidate_nll<=language_evals[i].reference_nll+language_tolerance&&language_evals[i].script_pass?"true":"false");}
